// The two kinds of a model's profiles: PRODUCTION and TEST (the owner's
// decision of 25 Nov: a profile is marked TEST or PRODUCTION in a stored
// field; that field is not built yet).
//
// THE INTERIM RULE, in this one place until the stored field exists:
// a profile is PRODUCTION when it was written by hand AND is placed
// automatically (no force_nodes). Everything else is a test: a profile
// pinned to zones (force_nodes), or one generated by a benchmark.
//
// A model's "profiles" are its production profiles ("2 profiles"); the rest
// is one line of its own ("40 test and benchmark configurations") and is
// never counted with them: the Models rows, the side panel and the delete
// dialog all read it from here.

import { plural } from '../../core/format.js';

// isProduction(profile) -> true for a production profile (the interim rule)
export const isProduction = p => !!p && !p.generated && !(Array.isArray(p.force_nodes) && p.force_nodes.length);

// splitProfiles(profiles) -> {prod, test}: the two lists, in their order
export function splitProfiles(ps) {
  const prod = [], test = [];
  for (const p of ps || []) (isProduction(p) ? prod : test).push(p);
  return { prod, test };
}

// prodText(n) -> "2 profiles", "1 profile", "No profiles"
export const prodText = n => (n ? plural(n, 'profile') : 'No profiles');
// testText(n) -> "1 test and benchmark configuration", "40 test and benchmark configurations"
export const testText = n => (n === 1 ? '1 test and benchmark configuration' : plural(n, 'test and benchmark configuration'));
